import React from "react";
import TitleCard from "./TitleCard/TitleCard";

const CardProject = (prop) => {



    return(
        <div className="listProject">
            {prop.map(project => (
                <TitleCard prop={project}/>
            ))}
        </div>
    )
}

export default CardProject;
